class _SecurityViewState extends ConsumerState<SecurityView> {
  bool _lock = false;

  Future<void> _duressToggled(bool newValue) async {
    if (_lock) return;
    try {
      _lock = true;

      if (newValue) {
        await _createDuressPin();
      } else {
        await _deleteDuressPin();
      }
    } finally {
      _lock = false;
    }
  }

  Future<void> _createDuressPin() async {
    final result = await showDialog<bool>(
      context: context,
      builder: (context) => StackDialogBase(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(l10n.duressEnable, style: STextStyles.pageTitleH2(context)),
            const SizedBox(height: 8),
            Row(
              children: [
                Flexible(
                  child: Text(
                    l10n.duressEnableText,
                    style: STextStyles.smallMed14(context),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 20),
            Row(
              children: [
                Expanded(
                  child: SecondaryButton(
                    label: l10n.commonCancel,
                    onPressed: () => Navigator.of(context).pop(false),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: PrimaryButton(
                    label: l10n.commonOk,
                    onPressed: () => Navigator.of(context).pop(true),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );

    if (result == true && mounted) {
      await Navigator.push(
        context,
        RouteGenerator.getRoute(
          shouldUseMaterialRoute: RouteGenerator.useMaterialPageRoute,
          builder: (_) => LockscreenView(
            showBackButton: true,
            routeOnSuccess: CreateDuressPinView.routeName,
            biometricsCancelButtonString: l10n.commonCancelCaps,
            biometricsLocalizedReason: l10n.duressAuthReason,
            biometricsAuthenticationTitle: l10n.duressCreate,
          ),
          settings: const RouteSettings(name: "/createDuressPinLockscreen"),
        ),
      );
    }
  }

  Future<void> _deleteDuressPin() async {
    final delete = await showDialog<bool>(
      context: context,
      builder: (context) => StackDialogBase(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(l10n.duressDisable, style: STextStyles.pageTitleH2(context)),
            const SizedBox(height: 8),
            Row(
              children: [
                Flexible(
                  child: Text(
                    l10n.duressDisableText,
                    style: STextStyles.smallMed14(context),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 20),
            Row(
              children: [
                Expanded(
                  child: SecondaryButton(
                    label: l10n.commonCancel,
                    onPressed: () => Navigator.of(context).pop(false),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: PrimaryButton(
                    label: l10n.commonDelete,
                    onPressed: () => Navigator.of(context).pop(true),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
    if (delete != true || !mounted) return;

    // Off only once the PIN is gone: the lock screen checks the stored
    // PIN, not this setting.
    try {
      await ref.read(secureStoreProvider).delete(key: kDuressPinKey);
    } catch (e, s) {
      Logging.instance.f(
        "Deleting the duress PIN failed",
        error: e,
        stackTrace: s,
      );
      return;
    }
    ref.read(prefsChangeNotifierProvider).hasDuressPin = false;
  }

